QTableWidget* table = ui->tbCalibrationResult;
std::vector<Seerain::CalibrationData> tb_results;
std::int32_t column = table->columnCount();
for(int i = 0; i < table->rowCount(); ++i)
{
    Seerain::CalibrationData item_data;
    if(table->cellWidget(i, 0) == nullptr || table->cellWidget(i, 1) == nullptr
            || table->cellWidget(i, column-kAfterMeasureColumn) == nullptr)
        continue;

    item_data.point_index = SystemCommon::widgetToLineEditGetText(table->cellWidget(i, 0)).toInt();
    item_data.concentration = SystemCommon::widgetToLineEditGetText(table->cellWidget(i, 2)).toFloat()/unitMultiple;
    std::int32_t repeat_times {0};
    double sum {0.0};
    for(int j = kBeforMeasureColumn; j < column - kAfterMeasureColumn; ++j)
    {
        QWidget* item = table->cellWidget(i, j);
        if(item == nullptr || table->cellWidget(i, 0) == nullptr)
            continue;
        Seerain::CalibrationItemData rst_value;
        bool flag = false;
        rst_value.result_value = SystemCommon::widgetToLineEditGetText(item).toDouble(&flag);
        //SystemCommon::widgetToLineEditSetText(item, QString::number(rst_value.result_value, 'f', result_point));//reset data to points
        sum += rst_value.result_value;
        item_data.results.push_back(std::move(rst_value));
        if(flag == true) //&&rst_value.result_value != 0)
            repeat_times++;
    }
    item_data.result_average = sum/repeat_times;
    SystemCommon::widgetToLineEditSetText(
                table->cellWidget(i, column-kAfterMeasureColumn),
                QString::number(item_data.result_average, 'f', result_point));

    tb_results.push_back(std::move(item_data));
}

