        QHash<QString,QString> reagentInfo =  reagentListTable.getReagentListDataByReagentName(reagentName);
        auto& bottleTypeTable = Seerain::ReagentBottleTypeTable::GetInstance();
        QHash<QString,QString> bottleInfo = bottleTypeTable.getBottleInfoByNameAndArea(bottleName, hole->getArea());
        R_ReagentType type = R_ReagentType(R_ReagentType_Str.indexOf(reagentInfo["reagent_type"]));
        if(reagentInfo.isEmpty() || bottleInfo.isEmpty())
            return;
        hole->setReagentName(reagentName);
        hole->setType(type);
        hole->setReagentBatch("Default");
        hole->setOutDate("");
        hole->setSetDate(QDateTime::currentDateTime().toString("yyyy/MM/dd HH:mm:ss"));
        hole->setBottleName(bottleName);
        maxVol = bottleInfo["max_amount_ul"].toDouble();
        hole->setMaxVol(maxVol);
        hole->setVol(maxVol);
        hole->setOutVol(reagentInfo["out_ul"].toDouble());
        hole->setWarnningUl(reagentInfo["warning_ul"].toDouble());
        hole->setUseVol(maxVol);
        hole->setPriority(99);
    }
    else
    {
        hole->clearHoleSet();
    }
};

