            auto& calibrationBatchTable = Seerain::CalibrationBatchGroupTable::GetInstance();
            unordered_map<string, vector<Seerain::CalibrationBatchData>> pgCarBatch =
                    calibrationBatchTable.getCalibrationBatchGroupData();
            vector<Seerain::CalibrationBatchData> carNeedAdd; // 储存复制的项目所有的batch
            for(auto pgNameBatch : pgCarBatch)
            {
                if(0 == oriName.compare(QString::fromStdString(pgNameBatch.first)))
                {
                    carNeedAdd = pgNameBatch.second;
                }
            }

            auto& calibrationTotalDate = Seerain::CalibrationTotalCountTable::GetInstance();
            auto totalDate = calibrationTotalDate.getCalibrationTotalCountData();
            for(auto it : carNeedAdd) // 循环原始batch
            {
                // 获取校准原始base
                auto& calibrationBaseTable = Seerain::CalibrationBaseTable::GetInstance();
                Seerain::CalibrationBaseData carBase =calibrationBaseTable.getSingleCalibrationDataByCaliId(
