                            oriName);
                // 获取校准原始数据
                auto& calibrationDateTable = Seerain::CalibrationDataTable::GetInstance();
                auto calibrationDateList = calibrationDateTable.getDataByCaliId(it.calibration_id);

                int copyID = totalDate.calibration_total_count; // 用于获取当前CARID序号
                totalDate.calibration_total_count++;
                it.project_name = projectInformation.projectBase["project_en_name"].toStdString();
                (void)it.batch_group;
                it.calibration_id = copyID;

                // 添加试剂组
                Seerain::ReagentBatchGroupData rgBatch;
                auto& reagentBatchTable = Seerain::ReagentBatchGroupTable::GetInstance();
                rgBatch.project_name = it.project_name;
                rgBatch.batch_group = it.batch_group;
                reagentBatchTable.Insert(rgBatch);

                // 添加carBatch
                calibrationBatchTable.Insert(it);
                // 添加carBase数据
                carBase.calibration_id = copyID;
                carBase.project_name = it.project_name;
                calibrationBaseTable.Insert(carBase);
                // 根据要复制id获取对应的校准数据，更新为新的ID添加新的carDATA
                for(auto calibrationDate : calibrationDateList)
                {
                    calibrationDate.calibration_id = copyID;
                    calibrationDateTable.Insert(calibrationDate);
                }
            }

            calibrationTotalDate.Update(totalDate);
            if(SystemCommon::isNewProtocal == true)
            {
                QString netFullPath     = QString("\\\\%1\\%2\\%3\\%4").arg(SHARE_IP, SHARE_NAME, "project", copyName);
                // 子线程执行，主线程完全不卡
                QtConcurrent::run([=]() {
                    SystemCommon::copyFileToShareSafe(ProjectPath + copyName, netFullPath);
                });
            }
            emit Signal_ProjectChanged();
        }
    }
