//}

CusMessageBox *cusMessageBox = new CusMessageBox;
cusMessageBox->showQuestionBox("确认删除用户？");
bool result = cusMessageBox->getClickButton()==QMessageBox::Yes;
cusMessageBox->deleteLater();
if(!result)
{
    return;
}
if((ui->ldtUserNameDel->text() == SystemCommon::userRoleName)
        && (false == SystemCommon::driverInformation.actionReady))
{
    CusMessageBox *cusMessageBox = new CusMessageBox;
    cusMessageBox->showWarningBox("设备正在运行，不允许删除正在登陆账户!");
    cusMessageBox->deleteLater();
    return;
}

auto& userInfoTable = Seerain::UserInformationTable::GetInstance();
QHash<QString,QString> dataDel = userInfoTable.getUserInfoByName(ui->ldtUserNameDel->text());
if(dataDel.isEmpty())
{
    CusMessageBox *cusMessageBox = new CusMessageBox;
    cusMessageBox->showWarningBox("删除失败：用户名不存在!");
    cusMessageBox->deleteLater();
    return;
}
else if(dataDel["pwd"] != ui->ldtPasswordDel->text())
{
    CusMessageBox *cusMessageBox = new CusMessageBox;
    cusMessageBox->showWarningBox("删除失败：用户名或密码错误!");
    cusMessageBox->deleteLater();
    return;
}
else if(SystemCommon::permission < dataDel["role"].toUInt())
{
    CusMessageBox *cusMessageBox = new CusMessageBox;
    cusMessageBox->showWarningBox("删除失败：当前用户权限低于需要删除用户权限!");
    cusMessageBox->deleteLater();
    return;
}
else if(dataDel["role"].toUInt() ==  SystemCommon::Administrator)
{
    CusMessageBox *cusMessageBox = new CusMessageBox;
    cusMessageBox->showWarningBox("删除失败：超级用户不允许删除!");
    cusMessageBox->deleteLater();
    return;
}
else
{
    if(!userInfoTable.deleteUserInfoByName(ui->ldtUserNameDel->text()))
    {
        CusMessageBox *cusMessageBox = new CusMessageBox;
        cusMessageBox->showErrorBox("删除失败!");
        cusMessageBox->deleteLater();
        return;
    }
    else
    {
        CusMessageBox *cusMessageBox = new CusMessageBox;
        cusMessageBox->showInformationBox("删除成功!");
        cusMessageBox->deleteLater();
        // 如果删除的是当前登录账户，那么进行注销
        if(ui->ldtUserNameDel->text() == SystemCommon::userRoleName)
        {
            // 发送注销信号
            emit signalLoginOut();
        }
        ui->ldtUserNameDel->clear();
        ui->ldtPasswordDel->clear();
        frmGetAccount();

    }
}

// 如果设备正在运行，并且要更改用户类型，不允许
if((ui->cbxTypeSelectUpdate->currentIndex() == (SystemCommon::permission - 1))
        && (false == SystemCommon::driverInformation.actionReady))
{
    CusMessageBox *cusMessageBox = new CusMessageBox;
    cusMessageBox->showWarningBox("设备正在运行，不允许修改用户类型!");
    cusMessageBox->deleteLater();
    return;
}
auto& userInfoTable = Seerain::UserInformationTable::GetInstance();
QHash<QString,QString> dataDel = userInfoTable.getUserInfoByName(ui->ldtUserNameUpdate->text());
if(dataDel.isEmpty())
{
    CusMessageBox *cusMessageBox = new CusMessageBox;
    cusMessageBox->showWarningBox("更新失败: 用户名不存在!");
    cusMessageBox->deleteLater();
    return;
}
else if(dataDel["pwd"] != ui->ldtUserPasswordUpdate->text())
{
    CusMessageBox *cusMessageBox = new CusMessageBox;
    cusMessageBox->showWarningBox("更新失败: 用户名或密码错误!");
    cusMessageBox->deleteLater();
    return;
}
else if(ui->ldtUserPasswordUpdate3->text() != ui->ldtUserPasswordUpdate2->text())
{
    CusMessageBox *cusMessageBox = new CusMessageBox;
    cusMessageBox->showWarningBox("更新失败: 密码不一致,请重新输入!");
    cusMessageBox->deleteLater();
    return;
}
else if(ui->ldtUserNameUpdate2->text().isEmpty())// || ui->ldtUserPasswordUpdate2->text().isEmpty())
{
    CusMessageBox *cusMessageBox = new CusMessageBox;
    cusMessageBox->showWarningBox("更新失败: 用户名或密码不能为空!");
    cusMessageBox->deleteLater();
    return;
}
else
{
    auto& userRoleTable = Seerain::UserRoleTable::GetInstance();
    int roleId = userRoleTable.getIdByRole(ui->cbxTypeSelectUpdate->currentText());
    {
        Seerain::UserInformationData updateData;
        updateData.id = dataDel["id"].toInt();
        updateData.name = ui->ldtUserNameUpdate2->text().toStdString();
        updateData.pwd = ui->ldtUserPasswordUpdate2->text().toStdString();
        updateData.role = roleId;
        updateData.isdefault = dataDel["isdefault"].toInt();

        if(!userInfoTable.Update(updateData))
        {
            CusMessageBox *cusMessageBox = new CusMessageBox;
            cusMessageBox->showErrorBox("更新失败!");
            cusMessageBox->deleteLater();
            return;
        }
        else
        {
            CusMessageBox *cusMessageBox = new CusMessageBox;
            cusMessageBox->showInformationBox("更新成功!");
            cusMessageBox->deleteLater();
            ui->ldtUserPasswordUpdate->clear();
            ui->ldtUserPasswordUpdate2->clear();
            ui->ldtUserPasswordUpdate3->clear();
            //ui->cbxTypeSelectUpdate->setCurrentIndex(0);
            emit signalLoginOut();
            frmGetAccount();
        }
    }
}

hospitalDisplay type = hospitalROOM;
if(ui->btnKeShiInfo->isChecked())
    type = hospitalROOM;
else if(ui->btnBingRenInfo->isChecked())
    type = hospitalPATIENT;
else if(ui->btnShenHeInfo->isChecked())
    type = hospitalAUDIT;
else if(ui->btnSongJianInfo->isChecked())
    type = hospitalSEND;
else if(ui->btnJianYanInfo->isChecked())
    type = hospitalCHECK;
int row = ui->tableInfo->rowCount();
ui->tableInfo->insertRow(row);
QHash<QString,QString> dataAdd;
dataAdd["flag"] = "new";
addLineData(row, dataAdd,type);

ui->tableInfo->selectRow(row);
SystemCommon::eventFilter->addEventCtrl(ui->tableInfo);

if(showQuestionMessage(tr("是否删除当前选中信息?")))
{
    int row = ui->tableInfo->currentRow();
    if(row >= 0)
    {
        QString idSelect = ui->tableInfo->item(row,3)->text();
        if(!idSelect.isEmpty())
        {
            Seerain::HospitalInformationData delData;
            delData.id = idSelect.toInt();
            auto& hosInfoTable = Seerain::HospitalInformationTable::GetInstance();
            if(!hosInfoTable.Delete(delData))
            {
                showErrorMessage(tr("删除失败!"));
                return;
            }
        }
        ui->tableInfo->removeRow(row);
    }
}

QString nameSet = ui->ldtHospName->text();
if(SystemCommon::hospitalName != nameSet)
{
    if(nameSet.isEmpty())
    {
        showWarningMessage(tr("医院名称不能为空!"));
        return;
    }
    else
    {
        QSettings settings(pcConfigPath,QSettings::IniFormat);
        settings.setIniCodec(QTextCodec::codecForName("UTF-8"));
        settings.setValue("hospital/name",nameSet);
        SystemCommon::hospitalName = nameSet;
    }
}
for(int row = 0; row < ui->tableInfo->rowCount(); row++)
{
    QString flagSelect = ui->tableInfo->item(row,5)->text();
    QHash<QString,QString> dataChanged;
    dataChanged["column_one"] = qobject_cast< QLineEdit *>(ui->tableInfo->cellWidget(row,0))->text();
    dataChanged["column_two"] = qobject_cast< QLineEdit *>(ui->tableInfo->cellWidget(row,1))->text();
    dataChanged["column_three"] = qobject_cast< QLineEdit *>(ui->tableInfo->cellWidget(row,2))->text();

    QString sqlWhere;
    if(ui->btnKeShiInfo->isChecked())
    {
        sqlWhere = "keshi";
        if(dataChanged["column_one"].isEmpty())
        {
            showWarningMessage(tr("科室信息不能为空!"));
            return;
        }
    }
    else if(ui->btnBingRenInfo->isChecked())
    {
        sqlWhere = "bingren";
        if(dataChanged["column_one"].isEmpty())
        {
            showWarningMessage(tr("病人信息不能为空!"));
            return;
        }
    }
    else
    {
        if(dataChanged["column_one"].isEmpty())
        {
            showWarningMessage(tr("医生信息不能为空!"));
            return;
        }
    }
    if(ui->btnShenHeInfo->isChecked())
        sqlWhere = "shenhe";
    else if(ui->btnSongJianInfo->isChecked())
        sqlWhere = "songjian";
    else if(ui->btnJianYanInfo->isChecked())
        sqlWhere = "jianyan";

    auto& hosInfoTable = Seerain::HospitalInformationTable::GetInstance();
    if(flagSelect == "new")
    {
        dataChanged["type"] = sqlWhere;
        if(!hosInfoTable.addDataByHash(dataChanged))
        {
            showErrorMessage(tr("保存失败!"));
            return;
        }
    }
    else
    {
        QString idSelect = ui->tableInfo->item(row,3)->text();
        QString typeSelect = ui->tableInfo->item(row,4)->text();
        dataChanged["id"] = idSelect;
        dataChanged["type"] = typeSelect;
        if(!hosInfoTable.updateDataByHash(dataChanged))
        {
            showErrorMessage(tr("保存失败!"));
            return;
        }
    }
}
slotDisplayButtonClicked();
showInformationMessage(tr("保存完成!"));

